import type { FormatOptions, SummaryData, TestRecord } from './types';
import { escapeMarkdown, formatDuration, formatPassRate } from './utils';

const FOOTER =
  '_Generated by [playwright-summary-reporter](https://www.npmjs.com/package/playwright-summary-reporter)_';

/**
 * Escapes a value used inside a Markdown table cell.
 *
 * This is the single place where pipe escaping happens — error messages arrive
 * here already collapsed to one line but *not* escaped, so escaping twice
 * would produce a stray double backslash.
 */
function cell(value: string): string {
  return escapeMarkdown(value.replace(/\r?\n/g, ' '));
}

/** Builds a GitHub-Flavored Markdown table from a header row and body rows. */
function table(headers: string[], rows: string[][]): string {
  const lines: string[] = [];

  lines.push(`| ${headers.join(' | ')} |`);
  lines.push(`| ${headers.map(() => '---').join(' | ')} |`);

  for (const row of rows) {
    lines.push(`| ${row.join(' | ')} |`);
  }

  return lines.join('\n');
}

/** The display title of a test. */
export function testTitle(record: TestRecord): string {
  return record.title;
}

/** Renders the "Failed Tests" table, or `undefined` when there are no failures. */
function renderFailedTests(tests: TestRecord[]): string | undefined {
  const failed = tests.filter((t) => t.outcome === 'failed' || t.outcome === 'timedOut');

  if (failed.length === 0) {
    return undefined;
  }

  const rows = failed.map((t) => [
    cell(testTitle(t)),
    cell(t.project),
    cell(`${t.file}:${t.line}`),
    cell(t.error ?? '—'),
  ]);

  return ['### ❌ Failed Tests', '', table(['Test', 'Project', 'Location', 'Error'], rows)].join('\n');
}

/** Renders the "Flaky Tests" table, or `undefined` when there are no flaky tests. */
function renderFlakyTests(tests: TestRecord[]): string | undefined {
  const flaky = tests.filter((t) => t.outcome === 'flaky');

  if (flaky.length === 0) {
    return undefined;
  }

  const rows = flaky.map((t) => [
    cell(testTitle(t)),
    cell(t.project),
    String(t.retries),
    formatDuration(t.duration),
  ]);

  return ['### ⚠️ Flaky Tests', '', table(['Test', 'Project', 'Retries', 'Duration'], rows)].join('\n');
}

/** Renders the "Slowest Tests" table, or `undefined` when disabled/empty. */
function renderSlowestTests(tests: TestRecord[], limit: number): string | undefined {
  if (limit <= 0) {
    return undefined;
  }

  const slowest = tests
    .filter((t) => t.outcome !== 'skipped')
    .sort((a, b) => b.duration - a.duration)
    .slice(0, limit);

  if (slowest.length === 0) {
    return undefined;
  }

  const rows = slowest.map((t) => [
    cell(testTitle(t)),
    cell(t.project),
    formatDuration(t.duration),
  ]);

  return ['### 🐢 Slowest Tests', '', table(['Test', 'Project', 'Duration'], rows)].join('\n');
}

/** Renders the per-project breakdown table, or `undefined` when there are none. */
function renderProjectBreakdown(projects: SummaryData['projects']): string | undefined {
  if (projects.length === 0) {
    return undefined;
  }

  const rows = projects.map((p) => [
    cell(p.project),
    String(p.total),
    String(p.passed),
    String(p.failed),
    String(p.flaky),
    String(p.skipped),
    formatDuration(p.duration),
  ]);

  return [
    '### 📊 Project Breakdown',
    '',
    table(['Project', 'Total', 'Passed', 'Failed', 'Flaky', 'Skipped', 'Duration'], rows),
  ].join('\n');
}

/**
 * Renders the complete Markdown report.
 */
export function formatSummary(data: SummaryData, options?: FormatOptions): string {
  const showSlowestTests = options?.showSlowestTests ?? 5;
  const includeProjectBreakdown = options?.includeProjectBreakdown ?? true;
  const showFailedTests = options?.showFailedTests ?? true;
  const showFlakyTests = options?.showFlakyTests ?? true;

  const sections: string[] = [];

  // Header & status.
  sections.push(`## ${data.title}`);
  sections.push('');
  sections.push(
    `**Status:** ${data.status} · **Duration:** ${formatDuration(data.duration)} · **Pass Rate:** ${formatPassRate(data.passRate)}`,
  );
  sections.push('');

  // Summary table.
  sections.push('### Summary');
  sections.push('');
  sections.push(
    table(
      ['Total', 'Passed', 'Failed', 'Flaky', 'Skipped', 'Duration', 'Pass Rate'],
      [[
        String(data.total),
        String(data.passed),
        String(data.failed),
        String(data.flaky),
        String(data.skipped),
        formatDuration(data.duration),
        formatPassRate(data.passRate),
      ]],
    ),
  );
  sections.push('');

  if (includeProjectBreakdown) {
    const breakdown = renderProjectBreakdown(data.projects);
    if (breakdown) {
      sections.push(breakdown);
      sections.push('');
    }
  }

  if (showFailedTests) {
    const failed = renderFailedTests(data.tests);
    if (failed) {
      sections.push(failed);
      sections.push('');
    }
  }

  if (showFlakyTests) {
    const flaky = renderFlakyTests(data.tests);
    if (flaky) {
      sections.push(flaky);
      sections.push('');
    }
  }

  const slowest = renderSlowestTests(data.tests, showSlowestTests);
  if (slowest) {
    sections.push(slowest);
    sections.push('');
  }

  sections.push(FOOTER);

  return `${sections.join('\n').replace(/\n{3,}/g, '\n\n').trimEnd()}\n`;
}
